p.me:
\text{How far left or right?}
\qquad
\text{How far up or down?}

\text{How far from the origin?}
\qquad
\text{At what angle?}

image.latex-image:
\begin{tikzpicture}[scale=1.2, every node/.style={font=\small}]
  % axes
  \draw[->, thick] (-0.4,0) -- (4.5,0) node[right] {\(x\)};
  \draw[->, thick] (0,-0.4) -- (0,3.0) node[above] {\(y\)};

  % point
  \coordinate (P) at ({3.2*cos(35)},{3.2*sin(35)});
  \draw[very thick] (0,0) -- (P);
  \fill (P) circle (2pt);
  \node[above right] at (P) {\(P=(r,\theta)\)};

  % angle
  \draw[->, thick] (0.75,0) arc (0:35:0.75);
  \node at (0.95,0.32) {\(\theta\)};

  % radius label
  \node[above] at ({1.6*cos(35)},{1.6*sin(35)+0.05}) {\(r\)};

  % projections
  \draw[dashed] (P) -- ({3.2*cos(35)},0);
  \draw[dashed] (P) -- (0,{3.2*sin(35)});
  \node[below] at ({3.2*cos(35)},0) {\(x\)};
  \node[left] at (0,{3.2*sin(35)}) {\(y\)};
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
    height=\textwidth,
    xmin=-2.3, xmax=2.3,
    ymin=-2.3, ymax=2.3,
    axis lines=middle,
    xtick={-2,0,2},
    ytick={-2,0,2},
    axis equal image,
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    title={\(r=2\)}
]
\addplot[very thick, domain=0:6.283185, samples=200]
    ({2*cos(deg(x))},{2*sin(deg(x))});
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
    height=\textwidth,
    xmin=-2.6, xmax=2.6,
    ymin=-2.6, ymax=2.6,
    axis lines=middle,
    xtick={-2,0,2},
    ytick={-2,0,2},
    axis equal image,
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    title={\(r=0.18\theta\)}
]
\addplot[very thick, domain=0:18.8495559, samples=350]
    ({0.18*x*cos(deg(x))},{0.18*x*sin(deg(x))});
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=0.58\textwidth,
    height=0.42\textwidth,
    xmin=-0.4, xmax=2.4,
    ymin=-1.4, ymax=1.4,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={0,1,2},
    ytick={-1,0,1},
    axis equal image,
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[very thick, domain=-1.5707963:1.5707963, samples=180]
    ({2*cos(deg(x))*cos(deg(x))},{2*cos(deg(x))*sin(deg(x))});
\addplot[only marks, mark=*] coordinates {(1,0)};
\node[anchor=south] at (axis cs:1,0) {center};
\node[anchor=west] at (axis cs:1.55,0.9) {\(r=2\cos\theta\)};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
    height=\textwidth,
    xmin=-2.3, xmax=2.3,
    ymin=-2.3, ymax=2.3,
    axis lines=middle,
    xtick={-2,0,2},
    ytick={-2,0,2},
    axis equal image,
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    title={\(r=2\cos(3\theta)\)}
]
\addplot[very thick, domain=0:6.283185, samples=500]
    ({2*cos(deg(3*x))*cos(deg(x))},{2*cos(deg(3*x))*sin(deg(x))});
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
    height=\textwidth,
    xmin=-2.3, xmax=2.3,
    ymin=-2.3, ymax=2.3,
    axis lines=middle,
    xtick={-2,0,2},
    ytick={-2,0,2},
    axis equal image,
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    title={\(r=1+\cos\theta\)}
]
\addplot[very thick, domain=0:6.283185, samples=400]
    ({(1+cos(deg(x)))*cos(deg(x))},{(1+cos(deg(x)))*sin(deg(x))});
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=0.64\textwidth,
    height=0.52\textwidth,
    xmin=-2.2, xmax=4.0,
    ymin=-2.8, ymax=3.0,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    ylabel style={at={(axis cs:0,3.0)}, anchor=east, xshift=-3pt},
    xtick={-2,-1,0,1,2,3},
    ytick={-2,-1,0,1,2},
    axis equal image,
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[very thick, domain=0:6.283185, samples=500]
    ({(1+2*cos(deg(x)))*cos(deg(x))},{(1+2*cos(deg(x)))*sin(deg(x))});
\node[anchor=south] at (axis cs:1.85,2.2) {\(r=1+2\cos\theta\)};
\node[anchor=west] at (axis cs:0.15,0.62) {inner loop};
\end{axis}
\end{tikzpicture}
